import { expect, Page } from '@playwright/test';
import { pp } from '../pricebook/pricebook-helpers';

export { ROLE, stamp } from '../pricebook/pricebook-helpers';
export { pp };

export const OFFLINE_TITLE = 'No internet connection';
export const OFFLINE_BODY = 'Lists cannot load and nothing can be saved until the connection is back.';
export const OFFLINE_SAVE = 'Nothing was saved. What you typed is still here';

/** Тестовый номер (555 — не настоящий абонент). */
export const TEST_PHONE = '2065550123';

export async function setEnglish(page: Page) {
  await page.addInitScript(() => {
    try { window.localStorage.setItem('preferred-language', 'en'); } catch { /* ignore */ }
  });
}

/** Полоса вверху экрана. */
export const offlineBanner = (page: Page) => page.getByRole('status').filter({ hasText: OFFLINE_BODY });

/** Сообщение о несохранении (тост внутри страницы). */
export const offlineSaveMessage = (page: Page) => page.getByText(OFFLINE_SAVE).filter({ visible: true }).first();

/** Собирает системные окна (alert/confirm) — их быть не должно. */
export function watchDialogs(page: Page): string[] {
  const dialogs: string[] = [];
  page.on('dialog', async (d) => {
    dialogs.push(`${d.type()}: ${d.message()}`);
    await d.dismiss().catch(() => {});
  });
  return dialogs;
}

export async function goOffline(page: Page) {
  await page.context().setOffline(true);
  await expect.poll(() => page.evaluate(() => navigator.onLine)).toBe(false);
}

export async function goOnline(page: Page) {
  await page.context().setOffline(false);
  await expect.poll(() => page.evaluate(() => navigator.onLine)).toBe(true);
}

/** Очистка (не роняет тест): Clients → поиск → клиент → Actions → Delete Customer → confirm. */
export async function deleteCustomer(page: Page, name: string) {
  if (page.isClosed()) return;
  try {
    await page.context().setOffline(false);
    for (let i = 0; i < 3; i++) {
      await page.goto(pp('/Customers'));
      await page.getByPlaceholder('Search clients...').fill(name);
      const hit = page.getByText(name, { exact: true }).filter({ visible: true });
      try {
        await expect(hit.first()).toBeVisible({ timeout: 8_000 });
      } catch {
        return; // клиентов с этим именем больше нет
      }
      await hit.first().click();
      await page.waitForURL(/\/CustomerDetail/);
      await page.getByRole('button', { name: 'Actions' }).filter({ visible: true }).first().click();
      page.once('dialog', (d) => d.accept().catch(() => {}));
      await page.getByRole('menuitem', { name: 'Delete Customer' }).click();
      await page.waitForURL(/\/Customers/);
    }
  } catch (e) {
    console.warn(`очистка клиента «${name}» не удалась — удалить вручную: ${String(e).slice(0, 200)}`);
  }
}
